MDJ([
{"n":"Contraception hormonale","i":"contraception","s":"gyneco","nn":["Contraceptifs œstroprogestatifs","Contraceptifs progestatifs","Progestatifs seuls","Dispositifs intra-utérins et traitements associés","Pilule","Implant contraceptif","DIU hormonal"],"d":["La **contraception hormonale** regroupe les **œstroprogestatifs** (pilule combinée, patch, anneau vaginal) et les **progestatifs seuls** (pilule microprogestative, implant, DIU hormonal, injection). Le choix se fait avec la personne selon ses besoins, ses contre-indications et ses préférences ; le **DIU au cuivre** est l'alternative non hormonale.","Elle est accessible aux mineures de façon gratuite et confidentielle ; la prise en charge est gratuite pour les moins de 26 ans."],"ma":["Les **œstroprogestatifs** bloquent l'**ovulation** par rétrocontrôle sur l'hypothalamus et l'hypophyse (moins de FSH et de LH), épaississent la glaire et amincissent l'endomètre. Les **progestatifs** agissent surtout sur la **glaire** cervicale et l'endomètre, et bloquent l'ovulation pour certains (désogestrel, implant)."],"sch":{"k":"menstru","cap":"La contraception œstroprogestative supprime le pic de LH : il n'y a plus d'ovulation."},"m":[{"dci":"Éthinylestradiol + lévonorgestrel","br":"Minidril®, Leeloo®, Optilova®","pr":"pilules de 2e génération (référence)"},{"dci":"Patch, anneau vaginal","br":"Evra®, Nuvaring® et génériques","pr":"œstroprogestatifs (patch hebdomadaire, anneau 3 semaines)"},{"dci":"Désogestrel","br":"Optimizette® et génériques","pr":"pilule progestative (retard toléré de 12 h)"},{"dci":"Étonogestrel implant","br":"Nexplanon®","pr":"implant sous-cutané au bras, 3 ans"},{"dci":"DIU au lévonorgestrel","br":"Mirena®, Kyleena®, Jaydess®","pr":"3 à 8 ans selon le modèle"},{"dci":"Médroxyprogestérone","br":"Depo-Provera®","pr":"injection IM tous les 3 mois"}],"ind":["**Contraception** réversible","Règles douloureuses ou abondantes, acné (certaines pilules), endométriose (progestatifs)"],"ci":["Œstroprogestatifs : **antécédent de thrombose** veineuse ou artérielle, **tabagisme après 35 ans**, **migraine avec aura**, HTA non contrôlée, diabète compliqué, thrombophilie connue, **cancer du sein**, maladie hépatique sévère, **post-partum** précoce","Progestatifs : cancer du sein, saignement génital inexpliqué, maladie hépatique sévère","Contre-indications très limitées pour le DIU au cuivre et l'implant (préférés en cas de risque vasculaire)"],"ef":["Œstroprogestatifs : nausées, tension mammaire, céphalées, saignements entre les règles, troubles de l'humeur","Progestatifs : **saignements irréguliers** ou absence de règles, acné, prise de poids (injection)","DIU : douleurs à la pose, règles modifiées"],"eg":["Œstroprogestatifs : **thrombose veineuse** (phlébite, embolie pulmonaire), **AVC**, infarctus (surtout chez la fumeuse)","DIU : expulsion, perforation (rare), infection à la pose","Injection de médroxyprogestérone : perte osseuse (usage prolongé)"],"it":["**Inducteurs enzymatiques** (rifampicine, carbamazépine, phénytoïne, millepertuis, certains antirétroviraux, modafinil) : **contraception hormonale orale inefficace**","Sugammadex : efficacité diminuée pendant 7 jours","Vomissements dans les 3 à 4 heures après la prise : considérer comme un oubli"],"v":["Pilule : **à heure fixe**, schéma 21 jours + 7 jours d'arrêt ou en continu selon la pilule","**Oubli** d'une pilule combinée : **moins de 12 h** de retard → la prendre et continuer normalement ; **plus de 12 h** → la prendre, continuer, **préservatif pendant 7 jours**, **contraception d'urgence** si rapport dans les 5 jours précédents","Implant et DIU : pose et retrait par un médecin ou une sage-femme formés"],"sc":["Tension artérielle, poids, tabac, migraines","Tolérance (saignements, humeur), observance","Signes de thrombose : douleur ou gonflement d'un mollet, essoufflement, douleur thoracique, céphalées inhabituelles, troubles de la vision ou de la parole"],"sb":["Bilan glucidolipidique selon les facteurs de risque ; bilan de thrombophilie si antécédent familial"],"p":["Adolescente : confidentialité, gratuité, préservatif en plus contre les IST","Après 35 ans et fumeuse : œstroprogestatifs contre-indiqués","Post-partum et allaitement : progestatifs possibles tôt ; œstroprogestatifs à éviter les 6 premières semaines (thrombose)","Insuffisance hépatique : contre-indication des hormones si sévère"],"edu":["Expliquer la conduite à tenir en cas d'**oubli** et de **vomissements**","**Arrêter de fumer** ; signaler tout signe de thrombose","Le **préservatif** reste indispensable contre les IST","Signaler tout nouveau traitement (interactions)"],"cat":["Douleur du mollet, essoufflement, douleur thoracique, signes neurologiques : **urgence**","Oubli de plus de 12 h avec rapport récent : orienter vers une **contraception d'urgence**","Prescription d'un inducteur enzymatique : conseiller une contraception non hormonale ou un DIU"],"r":["Œstroprogestatifs : bloquent l'ovulation ; risque de **thrombose** (tabac, âge, migraine avec aura)","**Oubli > 12 h** : prendre, continuer, préservatif 7 jours, contraception d'urgence si rapport dans les 5 jours","**Inducteurs enzymatiques** = pilule inefficace","Préservatif contre les IST"],"err":[],"q":[{"q":"Que faire en cas d'oubli de pilule combinée de plus de 12 heures ?","o":["Arrêter la plaquette","Prendre la pilule oubliée, continuer, utiliser un préservatif pendant 7 jours et une contraception d'urgence si rapport dans les 5 jours précédents","Prendre deux pilules chaque jour pendant une semaine"],"a":1,"e":"Au-delà de 12 h, l'ovulation n'est plus bloquée de façon fiable."},{"q":"Laquelle de ces situations contre-indique une pilule œstroprogestative ?","o":["Une femme de 22 ans non fumeuse","Une migraine avec aura","Des règles douloureuses"],"a":1,"e":"La migraine avec aura augmente le risque d'AVC sous œstrogènes."}],"f":["m:contraception-urgence"]},
{"n":"Contraception d'urgence","i":"contraception-urgence","s":"gyneco","nn":["Contraception d'urgence","Pilule du lendemain","Lévonorgestrel","Ulipristal"],"d":["La **contraception d'urgence** prévient une grossesse après un rapport non ou mal protégé (oubli de pilule, préservatif qui craque). Elle est **d'autant plus efficace qu'elle est prise tôt**. La contraception d'urgence hormonale est **disponible sans ordonnance et gratuitement en pharmacie pour toutes**, et délivrée par les infirmiers scolaires."],"ma":["Le **lévonorgestrel** et l'**ulipristal** **retardent ou bloquent l'ovulation** ; ils n'interrompent pas une grossesse déjà implantée. Le **DIU au cuivre** posé en urgence empêche la fécondation et l'implantation : c'est la méthode la plus efficace."],"sch":null,"m":[{"dci":"Lévonorgestrel 1,5 mg","br":"Norlevo® et génériques","pr":"dans les **72 heures** (3 jours)"},{"dci":"Ulipristal acétate 30 mg","br":"EllaOne®","pr":"dans les **120 heures** (5 jours)"},{"dci":"DIU au cuivre","br":"plusieurs modèles","pr":"dans les **5 jours**, méthode la plus efficace"}],"ind":["Rapport sexuel non protégé ou mal protégé, oubli de contraception, violence sexuelle"],"ci":["Hypersensibilité","Grossesse connue (inefficace, mais non dangereuse)","Ulipristal : asthme sévère sous corticoïdes oraux"],"ef":["Nausées, céphalées, douleurs abdominales, tension mammaire","Règles en avance ou en retard, saignements"],"eg":["Rares ; une grossesse extra-utérine doit être évoquée en cas de retard de règles avec douleurs"],"it":[],"v":[],"sc":["Date des règles suivantes","Douleurs abdominales, saignements anormaux"],"sb":["**Test de grossesse** si les règles ont plus de 5 à 7 jours de retard ; dépistage des IST"],"p":[],"edu":[],"cat":[],"r":["Lévonorgestrel : **72 h** ; ulipristal : **120 h** ; DIU au cuivre : **5 jours** (le plus efficace)","Le plus tôt possible ; vomissement dans les 3 h = reprendre","Préservatif jusqu'aux règles, test de grossesse si retard, dépistage des IST"],"err":[],"q":[],"f":["m:contraception"],"_l":1},
{"n":"Traitement hormonal de la ménopause et traitements gynécologiques","i":"thm","s":"gyneco","nn":["Traitements hormonaux de la ménopause","Traitements de substitution hormonale","Traitements de l'endométriose","Traitements hormonaux des troubles gynécologiques","Inducteurs de l'ovulation","Analogues de la GnRH en gynécologie"],"d":["Le **traitement hormonal de la ménopause** (THM) soulage les **bouffées de chaleur**, les troubles du sommeil et la sécheresse vaginale lorsqu'ils altèrent la qualité de vie. Il est prescrit à la **dose minimale efficace**, réévalué chaque année, en tenant compte des risques (cancer du sein, thrombose)."],"ma":["Le THM apporte les **œstrogènes** que les ovaires ne produisent plus, associés à un **progestatif** chez la femme qui a encore son utérus (pour éviter le cancer de l'endomètre). Dans l'endométriose, les progestatifs et les analogues de la GnRH mettent les lésions au repos ; les inducteurs (clomifène, gonadotrophines) stimulent l'ovulation."],"sch":null,"m":[{"dci":"Estradiol","br":"Oestrodose®, Estreva® (gel), Vivelledot® (patch)","pr":"voie cutanée (moins de risque thrombotique)"},{"dci":"Progestérone micronisée","br":"Utrogestan®","pr":"associée si utérus présent"},{"dci":"Estriol, promestriène","br":"Trophicrème®, Colpotrophine®","pr":"traitement local de la sécheresse vaginale"},{"dci":"Diénogest","br":"Visanne®","pr":"endométriose"},{"dci":"Clomifène, gonadotrophines","br":"Clomid®, Gonal-f®","pr":"induction de l'ovulation (PMA)"}],"ind":["Symptômes de la ménopause gênants (bouffées de chaleur, sueurs, troubles du sommeil, de l'humeur, sécheresse vaginale)","Ménopause précoce (avant 40 ans)","Endométriose douloureuse ; infertilité par trouble de l'ovulation"],"ci":["**Cancer du sein** ou de l'endomètre (actuel ou passé), **antécédent de thrombose** ou d'AVC, maladie coronaire","Saignement génital inexpliqué, maladie hépatique sévère"],"ef":["Tension mammaire, saignements, céphalées, nausées","Ballonnements, troubles de l'humeur"],"eg":["Augmentation du risque de **cancer du sein** (durée prolongée, association avec certains progestatifs)","**Thrombose veineuse** et **AVC** (surtout œstrogènes par voie orale)","Stimulation ovarienne : syndrome d'hyperstimulation, grossesses multiples"],"it":[],"v":[],"sc":["Bouffées de chaleur, sommeil, tolérance, saignements","Tension artérielle, poids, signes de thrombose"],"sb":["**Mammographie** régulière (dépistage), examen gynécologique ; bilan lipidique et glucidique selon les facteurs de risque"],"p":[],"edu":[],"cat":[],"r":["THM : œstrogène (cutané de préférence) + **progestatif si utérus présent**","Dose minimale, **réévaluation annuelle** ; risques : cancer du sein, thrombose, AVC","Contre-indiqué si antécédent de cancer du sein ou de thrombose"],"err":[],"q":[],"f":["m:contraception","m:osteoporose"],"_l":1},
{"n":"Ocytociques et utérotoniques","i":"ocytociques","s":"gyneco","nn":["Ocytociques","Utérotoniques","Prostaglandines obstétricales","Traitements des hémorragies du post-partum","Ocytocine","Syntocinon","Sulprostone"],"d":["Les **utérotoniques** font contracter l'utérus. L'**ocytocine** est utilisée pour **déclencher ou accélérer le travail** et pour **prévenir et traiter l'hémorragie du post-partum** (première cause de mortalité maternelle). Les **prostaglandines** servent à la maturation du col et, pour la sulprostone, au traitement de l'hémorragie résistante."],"ma":["L'**ocytocine** stimule les récepteurs de l'utérus (contractions) et des seins (éjection du lait). Après l'accouchement, la **rétraction utérine** ferme les vaisseaux du site placentaire : c'est le principal mécanisme d'arrêt du saignement. Les prostaglandines (dinoprostone, misoprostol, sulprostone) ramollissent le col et font contracter l'utérus."],"sch":null,"m":[{"dci":"Ocytocine","br":"Syntocinon®","pr":"perfusion IV au pousse-seringue (travail), IV lente ou IM (délivrance)"},{"dci":"Carbétocine","br":"Pabal®","pr":"prévention de l'hémorragie lors d'une césarienne"},{"dci":"Sulprostone","br":"Nalador®","pr":"hémorragie du post-partum résistante à l'ocytocine"},{"dci":"Dinoprostone","br":"Propess® (dispositif vaginal), Prostine E2®","pr":"maturation du col avant déclenchement"},{"dci":"Misoprostol","br":"Angusta®","pr":"déclenchement par voie orale ; IVG médicamenteuse (autres spécialités)"},{"dci":"Acide tranexamique","br":"Exacyl®","pr":"hémorragie du post-partum (voir antifibrinolytiques)"}],"ind":["**Déclenchement** ou **direction du travail** (ocytocine, prostaglandines)","**Prévention de l'hémorragie du post-partum** : ocytocine à la naissance (délivrance dirigée)","**Hémorragie du post-partum** : ocytocine, puis sulprostone si échec, acide tranexamique","Interruption volontaire de grossesse médicamenteuse (mifépristone puis misoprostol)"],"ci":["Ocytocine (pendant le travail) : **disproportion fœto-pelvienne**, présentation anormale, souffrance fœtale, utérus cicatriciel (prudence), hypercinésie","Sulprostone : **maladie cardiovasculaire**, asthme sévère, tabagisme important et âge > 35 ans (prudence), insuffisance rénale ou hépatique","Prostaglandines de maturation : utérus cicatriciel (selon les produits), allergie"],"ef":["Ocytocine : nausées, vomissements, céphalées","Prostaglandines : nausées, vomissements, diarrhée, fièvre, frissons"],"eg":["Ocytocine : **hypercinésie et hypertonie utérines** (souffrance fœtale, rupture utérine), **intoxication par l'eau** (hyponatrémie) à forte dose prolongée, hypotension en bolus rapide","Sulprostone : **infarctus**, spasme coronaire, troubles du rythme, bronchospasme","Prostaglandines de maturation : hyperstimulation utérine"],"it":[],"v":[],"sc":["**Contractions utérines** (fréquence, intensité, tonus de base), **rythme cardiaque fœtal** (monitoring)","Après l'accouchement : **globe utérin** (dur et rétracté), **saignements** quantifiés (sac de recueil), pouls, tension, conscience","Sous sulprostone : scope, tension, douleur thoracique"],"sb":["NFS, coagulation, fibrinogène, groupe sanguin et RAI en cas d'hémorragie ; natrémie si ocytocine prolongée"],"p":[],"edu":[],"cat":[],"r":["Ocytocine : travail (pompe, débit progressif, **monitoring**) et **prévention de l'hémorragie** (5 à 10 UI)","Hémorragie du post-partum > 500 mL : **globe utérin**, massage, ocytocine, sulprostone, acide tranexamique","Sulprostone : **contre-indiquée chez la cardiaque**, jamais en bolus","Ocytocine : hypercinésie utérine, souffrance fœtale"],"err":[],"q":[],"f":["m:antifibrinolytiques","m:tocolytiques"],"_l":1},
{"n":"Tocolytiques et corticothérapie anténatale","i":"tocolytiques","s":"gyneco","nn":["Tocolytiques","Traitements de la prématurité","Menace d'accouchement prématuré","Atosiban","Nifédipine"],"d":["Les **tocolytiques** arrêtent les contractions utérines en cas de **menace d'accouchement prématuré** (avant 37 SA, surtout avant 34 SA). Leur but principal est de **gagner 48 heures** pour administrer une **corticothérapie anténatale** (maturation des poumons du fœtus) et permettre un **transfert** vers une maternité adaptée au terme."],"ma":["L'**atosiban** bloque les récepteurs de l'ocytocine ; la **nifédipine** (inhibiteur calcique) relâche le muscle utérin. La **bétaméthasone** accélère la maturation des poumons du fœtus (production de surfactant) et diminue la mortalité et les complications néonatales."],"sch":null,"m":[{"dci":"Atosiban","br":"Tractocile®","pr":"IV : bolus puis perfusion sur 48 h"},{"dci":"Nifédipine","br":"Adalate®","pr":"voie orale (hors AMM, très utilisée)"},{"dci":"Bétaméthasone","br":"Célestène®","pr":"**12 mg IM, 2 injections à 24 heures d'intervalle**"},{"dci":"Sulfate de magnésium","br":"sulfate de magnésium","pr":"neuroprotection fœtale avant 32 SA (voir fiche)"}],"ind":["**Menace d'accouchement prématuré** entre 24 et 34 SA environ, selon le contexte","Corticothérapie anténatale : risque d'accouchement prématuré avant 34 SA (y compris césarienne programmée précoce)"],"ci":["Tocolyse : **chorioamniotite** (infection), **hémorragie** maternelle importante, souffrance fœtale, prééclampsie sévère, mort fœtale","Nifédipine : hypotension, cardiopathie maternelle"],"ef":["Atosiban : nausées, céphalées, réaction au point d'injection","Nifédipine : **hypotension**, tachycardie, céphalées, bouffées de chaleur","Bétaméthasone : **hyperglycémie** maternelle transitoire"],"eg":["Nifédipine : hypotension sévère, œdème pulmonaire (association à d'autres tocolytiques)","Corticoïdes : déséquilibre d'un diabète maternel"],"it":[],"v":[],"sc":["**Contractions** (tocométrie), **rythme cardiaque fœtal**, col (par la sage-femme)","Tension, pouls (nifédipine), température (infection), pertes (liquide, sang)","Glycémie après les corticoïdes (surtout chez la diabétique)"],"sb":["NFS, CRP, ECBU, prélèvement vaginal (recherche d'infection), glycémie"],"p":[],"edu":[],"cat":[],"r":["Tocolyse : **gagner 48 h** pour la **corticothérapie anténatale** et le transfert","Bétaméthasone : **12 mg IM × 2 à 24 h d'intervalle**","Contre-indiquée en cas d'infection ou d'hémorragie ; nifédipine : hypotension"],"err":[],"q":[],"f":["m:ocytociques","m:sulfate-mg-obst","m:corticoides"],"_l":1},
{"n":"Sulfate de magnésium et prééclampsie","i":"sulfate-mg-obst","s":"gyneco","nn":["Sulfate de magnésium en obstétrique","Traitements de la prééclampsie","Éclampsie","Antihypertenseurs de la grossesse"],"d":["La **prééclampsie** associe une **hypertension** apparue après 20 SA et une **protéinurie** (ou une atteinte d'organe). Ses formes sévères menacent la mère (éclampsie, HELLP syndrome, AVC, œdème pulmonaire) et l'enfant. Le seul traitement curatif est l'**accouchement** ; les médicaments contrôlent la tension et préviennent les convulsions."],"ma":["Le **magnésium** stabilise les membranes des neurones et a un effet vasodilatateur cérébral : il prévient les convulsions. Les **antihypertenseurs** (nicardipine, labétalol, urapidil) abaissent la tension sans la faire chuter trop vite (perfusion placentaire). L'**aspirine** à faible dose prévient la prééclampsie chez la femme à risque."],"sch":null,"m":[{"dci":"Sulfate de magnésium","br":"sulfate de magnésium 15 %","pr":"**4 g IV en 20 minutes** puis **1 g/h** selon le protocole"},{"dci":"Nicardipine","br":"Loxen®","pr":"IV au pousse-seringue (HTA sévère)"},{"dci":"Labétalol","br":"Trandate®","pr":"IV ou oral"},{"dci":"Urapidil","br":"Eupressyl®","pr":"IV"},{"dci":"Aspirine faible dose","br":"Kardégic®","pr":"prévention chez la femme à haut risque, de 12 à 36 SA, le soir"},{"dci":"Gluconate de calcium","br":"gluconate de calcium 10 %","pr":"**antidote** du surdosage en magnésium"}],"ind":["**Prééclampsie sévère** (prévention de l'éclampsie), **crise d'éclampsie**","**Neuroprotection fœtale** en cas d'accouchement prématuré avant 32 SA","HTA sévère de la grossesse (nicardipine, labétalol)","Prévention de la prééclampsie chez la femme à risque (aspirine)"],"ci":["Magnésium : **insuffisance rénale sévère** (adapter), myasthénie, bloc de conduction","Labétalol : asthme ; nicardipine : hypotension"],"ef":["Magnésium : **bouffées de chaleur**, sensation de chaleur, nausées, faiblesse","Nicardipine : céphalées, tachycardie, veinite"],"eg":["**Surdosage en magnésium** : **abolition des réflexes ostéotendineux**, **dépression respiratoire**, troubles de conscience, arrêt cardiaque","Hypotension brutale (antihypertenseurs) : souffrance fœtale"],"it":[],"v":[],"sc":["Sous magnésium, au moins toutes les heures : **réflexes ostéotendineux** (rotuliens), **fréquence respiratoire** (> 12/min), **diurèse** (sonde, > 30 mL/h environ), **conscience**, SpO2","**Tension artérielle** rapprochée, céphalées, troubles visuels, douleur épigastrique (signes de gravité)","**Rythme cardiaque fœtal**, saignements, œdèmes"],"sb":["**Protéinurie**, NFS (plaquettes), transaminases, créatinine, uricémie, LDH, haptoglobine (HELLP) ; magnésémie si doute de surdosage"],"p":[],"edu":[],"cat":[],"r":["Prééclampsie : HTA + protéinurie après 20 SA ; traitement curatif = **accouchement**","**Sulfate de magnésium** : prévient l'éclampsie ; surveiller **ROT, FR, diurèse, conscience**","Antidote : **gluconate de calcium**","Antihypertenseurs sans baisse brutale ; aspirine préventive chez les femmes à risque"],"err":[],"q":[],"f":["m:calcium-mg","m:tocolytiques"],"_l":1},
{"n":"Immunoglobulines anti-D","i":"anti-d","s":"gyneco","nn":["Anti-D immunoglobulines","Immunoglobulines anti-D","Prévention de l'allo-immunisation rhésus","Rhophylac"],"d":["Les **immunoglobulines anti-D** préviennent l'**allo-immunisation rhésus** : chez une femme **rhésus négatif** portant un fœtus **rhésus positif**, le passage de globules rouges fœtaux dans son sang peut l'amener à fabriquer des anticorps anti-D, dangereux pour les grossesses suivantes (anémie fœtale grave, maladie hémolytique du nouveau-né)."],"ma":["Les anti-D injectées détruisent les globules rouges fœtaux rhésus positif passés dans le sang maternel **avant** que la mère ne fabrique ses propres anticorps (immunité passive temporaire)."],"sch":{"k":"immun","cap":"Les anti-D neutralisent les globules rouges fœtaux avant que la mère ne s'immunise."},"m":[{"dci":"Immunoglobulines anti-D","br":"Rhophylac® 200 µg","pr":"IV ou IM"}],"ind":["Femme **rhésus négatif** avec un fœtus rhésus positif (génotypage fœtal sur sang maternel) ou de rhésus inconnu","**Prévention systématique vers 28 SA**","**Dans les 72 heures** après un événement à risque : **accouchement** d'un enfant rhésus positif, fausse couche, IVG, grossesse extra-utérine, amniocentèse, traumatisme abdominal, saignement, version par manœuvre externe"],"ci":["Femme déjà immunisée (RAI positive pour l'anti-D) : inutile","Femme rhésus positif ; hypersensibilité aux immunoglobulines"],"ef":["Douleur au point d'injection, fièvre, frissons","Céphalées, nausées"],"eg":["Réaction allergique (rare)"],"it":[],"v":[],"sc":["Tolérance pendant et après l'injection","Événements à risque tout au long de la grossesse (saignement, chute)"],"sb":["**Groupe sanguin et rhésus**, **RAI** avant l'injection, **génotypage rhésus fœtal**, test de Kleihauer après l'accouchement ou un traumatisme, groupe du nouveau-né"],"p":[],"edu":[],"cat":[],"r":["Femme **Rh négatif**, fœtus Rh positif : anti-D à **28 SA** et **dans les 72 h** après tout événement à risque","**RAI avant**, Kleihauer pour adapter la dose","Médicament dérivé du sang : **traçabilité**"],"err":[],"q":[],"f":["m:immunoglobulines"],"_l":1},
{"n":"Médicaments chez l'enfant : principes et antalgiques-antipyrétiques","i":"pedia-principes","s":"pedia","nn":["Antalgiques pédiatriques","Antibiotiques pédiatriques","Antipyrétiques","Corticoïdes pédiatriques","Antihistaminiques pédiatriques","Insulines pédiatriques","Posologie pédiatrique"],"d":["Chez l'enfant, les médicaments se prescrivent et s'administrent **au poids** (mg/kg), avec des **formes galéniques adaptées** (solutions buvables, sachets, suppositoires). L'organisme de l'enfant, et surtout du nourrisson, élimine différemment les médicaments ; certains sont **contre-indiqués** (codéine, aspirine, mucolytiques avant 2 ans).","Les **erreurs de dose** (facteur 10, confusion de pipettes) sont fréquentes et graves : rigueur et double vérification sont indispensables."],"ma":["Les mécanismes d'action sont les mêmes que chez l'adulte, mais l'absorption, la distribution (plus d'eau), le métabolisme hépatique et l'élimination rénale varient avec l'âge : d'où des posologies calculées au **poids** et parfois à la surface corporelle."],"sch":null,"m":[{"dci":"Paracétamol","br":"Doliprane®, Dafalgan® pédiatriques","pr":"**15 mg/kg toutes les 6 heures** (60 mg/kg/jour)"},{"dci":"Ibuprofène","br":"Advil®, Nurofen® pédiatriques","pr":"**10 mg/kg toutes les 8 heures** (dès 3 mois)"},{"dci":"Amoxicilline","br":"Clamoxyl®","pr":"50 à 100 mg/kg/jour en 2 à 3 prises selon l'infection"},{"dci":"Bétaméthasone, prednisolone","br":"Célestène®, Solupred®","pr":"gouttes ou comprimés orodispersibles (laryngite, asthme)"},{"dci":"Morphine","br":"Oramorph®","pr":"douleur intense (0,2 mg/kg par prise en général)"}],"ind":["**Fièvre mal tolérée** et **douleur** (paracétamol en première intention, ibuprofène en seconde intention)","Infections bactériennes (otite, angine à streptocoque, pneumonie), asthme, laryngite"],"ci":["**Aspirine** chez l'enfant (syndrome de Reye en cas d'infection virale)","**Codéine** avant 12 ans, **tramadol** avant 3 ans","**Ibuprofène** : **varicelle**, déshydratation, infection bactérienne sévère, nourrisson de moins de 3 mois","Mucolytiques et antitussifs chez le nourrisson ; lopéramide avant 2 ans"],"ef":["Mêmes effets que chez l'adulte ; troubles digestifs fréquents (antibiotiques)","Refus de prise (goût), vomissements"],"eg":["**Surdosage** par erreur de calcul, de dispositif ou de concentration (facteur 10)","Paracétamol : hépatite en cas de surdosage ; ibuprofène : complications infectieuses (varicelle), insuffisance rénale si déshydratation"],"it":["Associer deux médicaments contenant le même principe actif (paracétamol)"],"v":["**Peser l'enfant** ; vérifier la dose en mg/kg et la **dose maximale** (jamais plus que la dose adulte)","Utiliser **uniquement la pipette ou le dispositif doseur fourni** avec le flacon (graduation en kg ou en mL propre au médicament) ; jamais une cuillère de cuisine","Mélanger si besoin à une petite quantité d'aliment (compote), jamais dans le biberon entier ; suppositoire si vomissements","Noter la date d'ouverture des suspensions (conservation limitée, parfois au réfrigérateur)"],"sc":["Température, douleur (échelles adaptées : EVENDOL, FLACC, EVA à partir de 6 ans), comportement","Hydratation, prise alimentaire, vomissements","Efficacité et tolérance du traitement"],"sb":["Selon la pathologie"],"p":["Nouveau-né et nourrisson : élimination immature, doses spécifiques ; paracétamol avec des intervalles adaptés","Enfant : traiter la douleur systématiquement (évaluation adaptée à l'âge), place des moyens non médicamenteux (sucre, succion, distraction, MEOPA, EMLA)","Adolescent : posologie adulte selon le poids"],"edu":["Fièvre : **traiter le confort**, pas un chiffre ; découvrir l'enfant, le faire boire souvent, pas de bain froid","Respecter les intervalles, ne pas associer deux médicaments contenant du paracétamol ; ranger les médicaments hors de portée","Consulter si fièvre chez un nourrisson de moins de 3 mois, troubles du comportement, taches sur la peau (purpura), difficultés respiratoires, refus de boire"],"cat":["Erreur de dose : prévenir immédiatement, centre antipoison, surveillance, déclaration","Fièvre avec purpura : **urgence absolue** (purpura fulminans : ceftriaxone, appel du 15)","Vomissement de la dose : attendre l'avis selon le délai et le médicament (ne pas redonner systématiquement)"],"r":["Dose au **poids** (mg/kg), jamais plus que la dose adulte ; **dispositif doseur du flacon**","Paracétamol **15 mg/kg/6 h** ; ibuprofène **10 mg/kg/8 h** dès 3 mois, jamais si varicelle","**Pas d'aspirine**, pas de codéine avant 12 ans","Double vérification des calculs (erreurs de facteur 10)"],"err":["Utiliser la pipette du Doliprane® pour administrer de l'Advil®"],"q":[{"q":"Quelle est la posologie du paracétamol chez l'enfant ?","o":["5 mg/kg par jour","15 mg/kg toutes les 6 heures (60 mg/kg/jour)","1 g par prise quel que soit le poids"],"a":1,"e":"La dose est calculée au poids : 15 mg/kg par prise, 4 fois par jour."},{"q":"Dans quelle situation l'ibuprofène est-il contre-indiqué chez l'enfant ?","o":["Une otite","Une varicelle","Une douleur dentaire"],"a":1,"e":"Pendant la varicelle, l'ibuprofène favorise des surinfections cutanées graves."}],"f":["s:douleur-pediatrique","m:paracetamol","m:ains","m:sro"]},
{"n":"Solutés de réhydratation orale (SRO)","i":"sro","s":"pedia","nn":["Solutés de réhydratation orale (SRO)","SRO","Gastro-entérite du nourrisson","Déshydratation de l'enfant"],"d":["Les **solutés de réhydratation orale** (SRO) sont le **traitement de référence** de la déshydratation due aux **gastro-entérites** chez le nourrisson et l'enfant. Bien utilisés, ils évitent la plupart des hospitalisations et des perfusions."],"ma":["Leur composition précise en **glucose et en sodium** utilise un transporteur intestinal qui absorbe le sodium avec le glucose, et l'eau suit : l'intestin absorbe l'eau même pendant une diarrhée. L'eau seule, les sodas ou les jus ne conviennent pas (trop sucrés, pas assez de sel)."],"sch":{"k":"compartiments","cap":"Les SRO compensent l'eau et les sels perdus par le secteur extracellulaire."},"m":[{"dci":"Solutés de réhydratation orale","br":"Adiaril®, Fanolyte®, Picolite®, GES 45®","pr":"sachets à diluer dans 200 mL d'eau"}],"ind":["**Diarrhée aiguë** et **vomissements** du nourrisson et de l'enfant (prévention et traitement de la déshydratation légère à modérée)","Personne âgée déshydratée (selon les cas)"],"ci":["Déshydratation **sévère** (perte de poids > 10 %, troubles de conscience, choc) : réhydratation IV","Vomissements incoercibles, occlusion, troubles de conscience"],"ef":["Vomissements si les prises sont trop rapides ou trop abondantes"],"eg":["Hypernatrémie si mauvaise dilution (sachet dans un volume d'eau trop faible)"],"it":[],"v":[],"sc":["**Poids** (perte en pourcentage), nombre de selles et de vomissements, volume de SRO bu","**Signes de déshydratation** : soif, pleurs sans larmes, bouche sèche, yeux cernés, fontanelle déprimée, pli cutané, diurèse diminuée (couches sèches), somnolence, tachycardie, extrémités froides","Conscience, comportement, fièvre"],"sb":["Ionogramme et glycémie si déshydratation importante ou hospitalisation"],"p":[],"edu":[],"cat":[],"r":["SRO : traitement de référence de la **gastro-entérite** de l'enfant","**1 sachet / 200 mL d'eau**, petites quantités fréquentes, **poursuivre l'allaitement**","Pas de sodas ni de jus ; peser l'enfant ; signes de déshydratation"],"err":[],"q":[],"f":["m:antidiarrheiques","m:pedia-principes"],"_l":1},
{"n":"Vitamines D et K chez l'enfant","i":"vitamines-nn","s":"pedia","nn":["Vitamine D","Vitamine K néonatale","Supplémentations vitaminiques","Supplémentation en vitamine D"],"d":["La **vitamine K** est donnée à **tous les nouveau-nés** pour prévenir la **maladie hémorragique du nouveau-né** (saignements digestifs, cérébraux). La **vitamine D** est recommandée **de la naissance à 18 ans** pour la croissance osseuse et la prévention du **rachitisme**."],"ma":["Le nouveau-né a peu de **vitamine K** (faible passage placentaire, lait maternel pauvre, flore intestinale absente) : la vitamine K permet au foie de fabriquer les facteurs de coagulation. La **vitamine D** permet l'absorption du calcium par l'intestin et la minéralisation de l'os."],"sch":null,"m":[{"dci":"Phytoménadione","br":"Vitamine K1 nourrissons® 2 mg/0,2 mL","pr":"voie orale (ou IM/IV)"},{"dci":"Cholécalciférol","br":"ZymaD®, Adrigyl®, Uvedose® (ampoule)","pr":"gouttes quotidiennes ou ampoules espacées"},{"dci":"Ergocalciférol","br":"Stérogyl®","pr":"gouttes"}],"ind":["**Vitamine K** : tout nouveau-né ; voie IM ou IV chez le prématuré ou le nouveau-né malade","**Vitamine D** : de la naissance à 18 ans (400 à 800 UI par jour selon l'âge et les facteurs de risque), personne âgée, femme enceinte"],"ci":["Hypersensibilité","Vitamine D : hypercalcémie, lithiase calcique"],"ef":["Rares aux doses recommandées"],"eg":["**Surdosage en vitamine D** : **hypercalcémie** (vomissements, constipation, soif, polyurie, perte de poids), lithiase et néphrocalcinose — surtout avec des **compléments alimentaires** très dosés ou des erreurs de produit","Vitamine K IV : réaction anaphylactoïde (rare)"],"it":[],"v":[],"sc":["Saignements (cordon, digestif, points de ponction) chez le nouveau-né","Croissance, développement moteur","Signes d'hypercalcémie en cas de surdosage"],"sb":["Calcémie, vitamine D (25-OH) en cas de suspicion de carence ou de surdosage"],"p":[],"edu":[],"cat":[],"r":["**Vitamine K** à tout nouveau-né : naissance, J4-J7, **1 mois si allaitement exclusif**","**Vitamine D** de la naissance à **18 ans**, sous forme de médicament","Surdosage en vitamine D = hypercalcémie (compléments alimentaires)"],"err":[],"q":[],"f":["m:pedia-principes","m:osteoporose"],"_l":1},
{"n":"Médicaments de la néonatalogie","i":"neonat","s":"pedia","nn":["Surfactants pulmonaires","Caféine en néonatalogie","Traitements de l'ictère néonatal","Photothérapie","Prématurité"],"d":["La **néonatalogie** utilise des traitements spécifiques du **nouveau-né**, en particulier du **prématuré** : **surfactant** pour la détresse respiratoire, **caféine** pour les apnées, **photothérapie** et parfois immunoglobulines pour l'**ictère**. Les doses sont très faibles et calculées au poids : les erreurs sont particulièrement graves."],"ma":["Le **surfactant** tapisse les alvéoles et les empêche de se collaber à l'expiration ; le prématuré en manque (maladie des membranes hyalines). La **caféine** stimule le centre respiratoire immature. La **photothérapie** (lumière bleue) transforme la bilirubine dans la peau en une forme éliminée par la bile et les urines."],"sch":{"k":"alveole","cap":"Le surfactant empêche les alvéoles du prématuré de se collaber."},"m":[{"dci":"Poractant alfa","br":"Curosurf®","pr":"administration intratrachéale (intubation ou technique peu invasive)"},{"dci":"Citrate de caféine","br":"Peyona®, citrate de caféine","pr":"IV ou oral, une fois par jour"},{"dci":"Photothérapie","br":"lampes, matelas à LED","pr":"lumière bleue"},{"dci":"Immunoglobulines IV, exsanguinotransfusion","br":"voir immunoglobulines","pr":"ictère hémolytique sévère"}],"ind":["**Détresse respiratoire du prématuré** (surfactant)","**Apnées du prématuré** (caféine)","**Ictère néonatal** avec bilirubine au-dessus des seuils selon l'âge et le terme (photothérapie)"],"ci":["Surfactant : hémorragie pulmonaire (prudence)","Caféine : tachycardie importante, convulsions non contrôlées","Photothérapie : porphyrie, ictère à bilirubine conjuguée (cholestase) qui nécessite un autre bilan"],"ef":["Surfactant : désaturation ou bradycardie transitoire pendant l'instillation, obstruction de la sonde","Caféine : **tachycardie**, agitation, intolérance digestive","Photothérapie : **hyperthermie** ou hypothermie, **déshydratation**, selles liquides, éruption, « bébé bronzé »"],"eg":["Surfactant : pneumothorax, hémorragie pulmonaire","Photothérapie : **atteinte rétinienne** si les yeux ne sont pas protégés","Ictère non traité : **encéphalopathie bilirubinique** (ictère nucléaire), séquelles neurologiques"],"it":[],"v":[],"sc":["Monitoring : **fréquence cardiaque**, **SpO2**, fréquence respiratoire, **apnées**, bradycardies","Photothérapie : **température** régulière, **hydratation** (poids, couches, selles), protection oculaire, peau","Coloration de la peau (ictère), comportement, succion"],"sb":["**Bilirubine** (transcutanée ou sanguine) selon le protocole, gaz du sang, glycémie, NFS, groupe sanguin et test de Coombs (ictère hémolytique)"],"p":[],"edu":[],"cat":[],"r":["Surfactant : détresse respiratoire du prématuré ; caféine : apnées","Photothérapie : enfant nu, **yeux protégés**, température, hydratation","Ictère avant 24 h ou selles décolorées : **pathologique**"],"err":[],"q":[],"f":["m:pedia-principes","m:vitamines-nn"],"_l":1},
{"n":"Dermocorticoïdes","i":"dermocorticoides","s":"dermato","nn":["Corticoïdes locaux","Dermocorticoïdes","Corticoïdes locaux et cutanés","Crème à la cortisone"],"d":["Les **dermocorticoïdes** sont des corticoïdes appliqués sur la peau. Ce sont les traitements de référence de l'**eczéma** (dermatite atopique, eczéma de contact), du **psoriasis** localisé et de nombreuses dermatoses inflammatoires. Bien utilisés, ils sont efficaces et sûrs ; la **corticophobie** des patients et des parents est une cause fréquente d'échec.","Ils sont classés en France en **4 niveaux d'activité** : très forte (classe 1), forte (classe 2), modérée (classe 3), faible (classe 4)."],"ma":["Ils diminuent l'**inflammation** locale, les démangeaisons et la prolifération des cellules de l'épiderme. Leur puissance et leur pénétration dépendent de la molécule, de la forme (pommade > crème > lotion), de la zone (paupières, plis et visage très perméables), de l'occlusion et de l'âge."],"sch":null,"m":[{"dci":"Clobétasol","br":"Dermoval®, Clarelux®","pr":"très forte activité (classe 1)"},{"dci":"Bétaméthasone","br":"Diprosone®, Betneval®","pr":"forte activité (classe 2)"},{"dci":"Désonide, fluocortolone","br":"Locapred®, Tridesonit®","pr":"activité modérée (classe 3)"},{"dci":"Hydrocortisone","br":"Hydracort®","pr":"faible activité (classe 4)"},{"dci":"Bétaméthasone + calcipotriol","br":"Daivobet®, Enstilar®","pr":"psoriasis"}],"ind":["**Eczéma** (dermatite atopique, eczéma de contact), **psoriasis**, lichen","Piqûres d'insectes étendues, dermatoses inflammatoires diverses"],"ci":["**Infections cutanées** non traitées (bactériennes, virales comme l'herpès ou la varicelle, fongiques), acné, rosacée","Ulcérations, plaies","Application sur les paupières et le visage avec des dermocorticoïdes forts (sauf avis spécialisé)"],"ef":["Picotements, sécheresse à l'application"],"eg":["**Atrophie cutanée** (peau fine), **vergetures**, télangiectasies, purpura (usage prolongé, classes fortes, zones fines)","**Dermite rosacéiforme** du visage, aggravation d'une acné ou d'une rosacée","Masquage ou aggravation d'une infection ; **effets généraux** (freination surrénalienne) chez le nourrisson ou en cas d'application très étendue sous occlusion","Glaucome ou cataracte si application prolongée sur les paupières"],"it":["Peu d'interactions"],"v":["**Une application par jour** en général, en couche fine, **sur peau légèrement humide** après la douche","Quantité : **une phalangette** (unité phalangette : longueur de crème sur la dernière phalange de l'index d'un adulte) couvre deux paumes d'adulte","Durée : jusqu'à disparition des lésions, puis **décroissance progressive** (espacement des applications) pour éviter le rebond","Se laver les mains après l'application (sauf si les mains sont traitées)"],"sc":["Évolution des lésions, démangeaisons, sommeil","Quantité utilisée (tubes par mois), zones traitées, signes d'atrophie","Signes d'infection (croûtes jaunes, vésicules)"],"sb":["Aucune en usage normal"],"p":["Nourrisson et enfant : peau plus perméable, classes modérées ou faibles, surface et durée limitées ; ne pas utiliser sous couche sans avis","Personne âgée : peau fine, risque d'atrophie","Grossesse et allaitement : utilisables ; ne pas appliquer sur le sein avant la tétée"],"edu":["**Rassurer** sur la sécurité du traitement bien conduit (corticophobie) : sous-traiter prolonge l'eczéma","Respecter la quantité, la zone et la durée ; appliquer un **émollient** chaque jour en complément","Ne pas utiliser sur une infection, ni sur le visage sans avis"],"cat":["Aggravation, lésions suintantes ou croûteuses : prévenir (surinfection)","Peau qui s'amincit, vergetures : prévenir (réévaluation)"],"r":["Eczéma et psoriasis : **1 application par jour**, couche fine, **unité phalangette**","4 classes (1 très forte à 4 faible) ; prudence au visage, aux plis, chez le nourrisson","**Décroissance progressive** ; atrophie si mal utilisés","Lutter contre la **corticophobie** ; associer un émollient"],"err":[],"q":[{"q":"Combien de surface couvre une unité phalangette de dermocorticoïde ?","o":["Tout le corps","Environ deux paumes de main d'adulte","Une seule tache de 1 cm²"],"a":1,"e":"L'unité phalangette (environ 0,5 g) permet de doser la quantité selon la surface à traiter."},{"q":"Quelle est la principale cause d'échec du traitement de l'eczéma par dermocorticoïdes ?","o":["Leur toxicité","La corticophobie qui conduit à un sous-traitement","Leur inefficacité"],"a":1,"e":"La peur de la cortisone fait utiliser trop peu de crème ou arrêter trop tôt : l'eczéma persiste."}],"f":["m:emollients","m:psoriasis"]},
{"n":"Émollients","i":"emollients","s":"dermato","nn":["Émollients","Crèmes hydratantes","Cold cream"],"d":["Les **émollients** hydratent et réparent la **barrière cutanée**. Ils sont la base du traitement de la **dermatite atopique** et de la **sécheresse cutanée** (personne âgée, ichtyose, psoriasis), et participent à la prévention des escarres et des dermites."],"ma":["Ils apportent des **lipides** qui reconstituent le film protecteur de la peau et limitent l'évaporation de l'eau ; certains contiennent des agents qui retiennent l'eau dans l'épiderme (glycérol, urée)."],"sch":null,"m":[{"dci":"Glycérol, vaseline, paraffine","br":"Dexeryl®","pr":"crème émolliente (remboursée)"},{"dci":"Cold cream, céramides","br":"Atoderm®, Lipikar®, Xeracalm®","pr":"nombreuses gammes"},{"dci":"Urée","br":"crèmes à l'urée","pr":"hyperkératose, talons fissurés"},{"dci":"Vaseline","br":"vaseline pure","pr":"lèvres, zones très sèches"}],"ind":["**Dermatite atopique** (traitement de fond quotidien), sécheresse cutanée (xérose) de la personne âgée","Psoriasis, ichtyose, peau sèche sous traitements (rétinoïdes, chimiothérapie, radiothérapie)","Soins de prévention cutanée (patient alité, mains des soignants)"],"ci":["Allergie à un composant (parfums, conservateurs, lanoline)","Peau infectée ou suintante (traiter d'abord)"],"ef":["Sensation de picotement sur peau très inflammatoire, aspect gras","Folliculite (produits très occlusifs)"],"eg":["Eczéma de contact à un composant","**Risque d'incendie** : les émollients à base de paraffine imprègnent textiles et pansements et les rendent **inflammables** (tabac, flammes, oxygène)"],"it":[],"v":[],"sc":["État de la peau (sécheresse, rougeur, prurit, lésions de grattage)","Tolérance, observance"],"sb":["Aucune"],"p":[],"edu":[],"cat":[],"r":["Base de la **dermatite atopique** et de la sécheresse cutanée : **quotidiennement**","Sur peau légèrement humide, après la toilette","Émollients paraffinés : **textiles inflammables** (tabac, flamme, oxygène)"],"err":[],"q":[],"f":["m:dermocorticoides"],"_l":1},
{"n":"Antiseptiques","i":"antiseptiques","s":"dermato","nn":["Antiseptiques cutanés","Antiseptiques","Désinfectants","Antiseptiques ORL","Chlorhexidine","Povidone iodée","Dakin"],"d":["Les **antiseptiques** éliminent ou inactivent les micro-organismes sur la **peau** et les **muqueuses** (tissus vivants). Ils sont indispensables à la **prévention des infections associées aux soins** : préparation cutanée avant un geste invasif (cathéter, ponction, chirurgie), soins de plaies, hygiène des mains."],"ma":["Ils détruisent les micro-organismes par différents mécanismes (altération des membranes, oxydation, dénaturation des protéines) : **alcools**, **chlorhexidine**, **dérivés iodés** (povidone iodée), **dérivés chlorés** (Dakin). Leur efficacité dépend du **temps de contact** et du **séchage**."],"sch":null,"m":[{"dci":"Chlorhexidine alcoolique 2 %","br":"Chlorhexidine alcoolique 2 % colorée ou incolore","pr":"référence pour les cathéters et la peau saine"},{"dci":"Povidone iodée","br":"Bétadine® scrub, dermique, alcoolique","pr":"peau, muqueuses (gynécologique)"},{"dci":"Hypochlorite de sodium","br":"Dakin® Cooper stabilisé","pr":"plaies, muqueuses"},{"dci":"Alcool à 70°","br":"alcool modifié","pr":"peau saine (avant une injection), désinfection de petits matériels"},{"dci":"Produits hydroalcooliques","br":"solutions, gels","pr":"**hygiène des mains** (friction)"}],"ind":["**Préparation cutanée** avant un geste invasif : pose et pansement de cathéter, prélèvement d'hémocultures, ponction, injection, chirurgie","**Soins des plaies** (selon les protocoles), muqueuses (soins de bouche, sondage)","Hygiène des mains (friction hydroalcoolique)"],"ci":["Allergie au produit (chlorhexidine : réactions graves rares ; iode)","Povidone iodée : **nouveau-né** et prématuré (thyroïde), 2e et 3e trimestres de grossesse et allaitement en usage prolongé ou étendu, dysthyroïdie","Chlorhexidine : contact avec les méninges, l'oreille moyenne (ototoxique), les yeux"],"ef":["Irritation, sécheresse, brûlure locale","Coloration de la peau (iode, chlorhexidine colorée)"],"eg":["**Allergie** grave à la chlorhexidine (anaphylaxie)","**Brûlures chimiques** (alcool sous champ ou sous le prématuré, produits non séchés au bloc)","Dysthyroïdie (iode chez le nouveau-né ou en usage étendu)"],"it":[],"v":[],"sc":["Peau : irritation, allergie, brûlure","Signes d'infection du site (rougeur, chaleur, écoulement)"],"sb":["Aucune ; TSH chez le nouveau-né exposé à l'iode si besoin"],"p":[],"edu":[],"cat":[],"r":["Antiseptique = **tissus vivants** ; désinfectant = surfaces et dispositifs","**Chlorhexidine alcoolique 2 %** pour les cathéters ; **temps de contact** et **séchage spontané**","**Jamais deux familles d'antiseptiques** successivement (inactivation)","Iode à éviter chez le nouveau-né ; date d'ouverture du flacon"],"err":[],"q":[],"f":["s:pansement-vvp","s:hemocultures","m:plaies"],"_l":1},
{"n":"Traitements de l'acné","i":"acne","s":"dermato","nn":["Traitements de l'acné","Rétinoïdes topiques","Rétinoïdes systémiques","Peroxyde de benzoyle","Isotrétinoïne"],"d":["L'**acné** est une maladie du follicule pilosébacé très fréquente à l'adolescence. Son traitement dépend de la sévérité : **traitements locaux** (peroxyde de benzoyle, rétinoïdes), **cyclines** orales, et pour les formes sévères **isotrétinoïne** orale, très efficace mais **tératogène majeure**."],"ma":["Le **peroxyde de benzoyle** est antibactérien (Cutibacterium acnes) ; les **rétinoïdes** (dérivés de la vitamine A) désobstruent les pores et diminuent la production de sébum ; l'**isotrétinoïne** orale réduit fortement les glandes sébacées. Les cyclines ont un effet anti-inflammatoire et antibactérien."],"sch":null,"m":[{"dci":"Peroxyde de benzoyle","br":"Cutacnyl®, Effacné®","pr":"gel, crème"},{"dci":"Adapalène, trétinoïne","br":"Differine®, Effederm® ; associé (Epiduo®)","pr":"rétinoïdes topiques"},{"dci":"Érythromycine, clindamycine locales","br":"Eryfluid®, Zindacline®","pr":"jamais seules (résistances)"},{"dci":"Doxycycline, lymécycline","br":"Doxy®, Tetralysal®","pr":"cyclines orales, 3 mois"},{"dci":"Isotrétinoïne","br":"Curacné®, Procuta®","pr":"acné sévère ; programme de prévention de la grossesse"}],"ind":["Acné légère à modérée : traitements locaux","Acné modérée à étendue : cycline orale + traitement local (3 mois maximum)","**Acné sévère** ou résistante : isotrétinoïne orale"],"ci":["**Isotrétinoïne et rétinoïdes topiques : grossesse** (malformations graves), allaitement","Isotrétinoïne : association aux **cyclines** (hypertension intracrânienne), insuffisance hépatique, hyperlipidémie importante","Cyclines : enfant de moins de 8 ans, grossesse"],"ef":["Locaux : **irritation**, sécheresse, rougeur, desquamation (premières semaines) ; le peroxyde de benzoyle **décolore** les textiles et les cheveux","Isotrétinoïne : **sécheresse des lèvres, de la peau, des yeux et du nez** (saignements), douleurs musculaires","Photosensibilité (rétinoïdes, cyclines)"],"eg":["Isotrétinoïne : **malformations fœtales**, **troubles de l'humeur, dépression, idées suicidaires**, hypertension intracrânienne, hépatite, hypertriglycéridémie","Cyclines : œsophagite, photosensibilité"],"it":[],"v":[],"sc":["Évolution de l'acné, tolérance cutanée","**Humeur**, comportement (isotrétinoïne), céphalées, troubles visuels","Sécheresse des muqueuses, douleurs articulaires"],"sb":["Isotrétinoïne : **test de grossesse** avant, chaque mois et 1 mois après ; **bilan lipidique** et **transaminases** avant puis régulièrement"],"p":[],"edu":[],"cat":[],"r":["Locaux : peroxyde de benzoyle, rétinoïdes (le soir, irritation au début, résultats en 6 à 12 semaines)","**Isotrétinoïne** : tératogène majeur, **contraception** et **tests de grossesse mensuels**, surveillance de l'**humeur**, lipides, foie","Jamais isotrétinoïne + cyclines ; antibiotiques locaux jamais seuls"],"err":[],"q":[],"f":["m:cyclines"],"_l":1},
{"n":"Traitements du psoriasis et de l'eczéma","i":"psoriasis","s":"dermato","nn":["Traitements du psoriasis","Immunomodulateurs topiques","Tacrolimus topique","Dermatite atopique","Photothérapie dermatologique"],"d":["Le **psoriasis** (plaques rouges épaisses recouvertes de squames, coudes, genoux, cuir chevelu) et la **dermatite atopique** (eczéma du nourrisson et de l'enfant, parfois de l'adulte) sont des maladies inflammatoires chroniques de la peau, évoluant par poussées, avec un retentissement important sur la qualité de vie."],"ma":["Les **dermocorticoïdes** et les **immunomodulateurs topiques** (tacrolimus) diminuent l'inflammation ; les **analogues de la vitamine D** (calcipotriol) freinent la prolifération des kératinocytes du psoriasis ; la **photothérapie** (UVB) a un effet immunomodulateur ; l'**acitrétine** (rétinoïde) normalise la kératinisation ; les **biothérapies** bloquent les cytokines de l'inflammation (IL-17, IL-23, IL-4/13)."],"sch":null,"m":[{"dci":"Dermocorticoïdes, calcipotriol","br":"Diprosone®, Daivonex®, Daivobet®","pr":"psoriasis localisé"},{"dci":"Tacrolimus pommade","br":"Protopic®","pr":"eczéma du visage et des plis, traitement d'entretien"},{"dci":"Méthotrexate, ciclosporine","br":"Metoject®, Néoral®","pr":"formes étendues"},{"dci":"Acitrétine","br":"Soriatane®","pr":"psoriasis ; tératogène (contraception 3 ans après l'arrêt)"},{"dci":"Aprémilast","br":"Otezla®","pr":"psoriasis (voie orale)"},{"dci":"Biothérapies","br":"Cosentyx®, Skyrizi®, Dupixent® (dermatite atopique)","pr":"formes sévères"}],"ind":["**Psoriasis** en plaques, du cuir chevelu, des ongles ; rhumatisme psoriasique associé","**Dermatite atopique** modérée à sévère"],"ci":["Tacrolimus topique : infection cutanée active, déficit immunitaire","**Acitrétine** : grossesse et femme sans contraception (pendant et **3 ans après**), alcool chez la femme","Ciclosporine : HTA non contrôlée, insuffisance rénale, cancer"],"ef":["Tacrolimus : **sensation de brûlure** et de chaleur les premiers jours","Calcipotriol : irritation","Acitrétine : sécheresse des lèvres et de la peau, chute de cheveux","Photothérapie : coup de soleil, vieillissement cutané"],"eg":["Infections (immunosuppresseurs, biothérapies)","Acitrétine : malformations fœtales, hépatite, hyperlipidémie","Ciclosporine : néphrotoxicité, HTA ; photothérapie : cancers cutanés (doses cumulées)"],"it":[],"v":[],"sc":["Étendue des lésions (surface, scores), démangeaisons, sommeil, qualité de vie, douleurs articulaires","Tolérance locale, signes d'infection","Humeur, retentissement psychologique et social"],"sb":["Selon le traitement systémique : NFS, bilan hépatique, créatinine, lipides, test de grossesse"],"p":[],"edu":[],"cat":[],"r":["Traitement **graduel** : local (dermocorticoïdes, calcipotriol, tacrolimus) → photothérapie → systémiques et biothérapies","Émollients quotidiens ; prise en charge globale (qualité de vie)","Acitrétine : **contraception pendant et 3 ans après** ; tacrolimus : brûlure au début, soleil"],"err":[],"q":[],"f":["m:dermocorticoides","m:methotrexate","m:biotherapies"],"_l":1},
{"n":"Topiques et pansements actifs des plaies, brûlures et escarres","i":"plaies","s":"dermato","nn":["Traitements des brûlures","Traitements des plaies et cicatrisants","Traitements des escarres","Produits de détersion et pansements médicamenteux","Sulfadiazine argentique","Flammazine","Pansements à l'argent"],"d":["Le choix d'un **topique** ou d'un **pansement actif** dépend du **stade de la plaie** (nécrose, fibrine, bourgeonnement, épidermisation), de l'**exsudat**, d'une éventuelle **infection** et de la localisation. Certains produits sont des médicaments (sulfadiazine argentique), d'autres des dispositifs médicaux (pansements à l'argent, hydrogels, alginates)."],"ma":["Les pansements maintiennent un **milieu humide** favorable à la cicatrisation, absorbent l'exsudat ou au contraire réhydratent, favorisent la **détersion** naturelle et protègent la plaie. L'**argent** et la **sulfadiazine argentique** ont un effet antibactérien local ; les alginates sont aussi hémostatiques."],"sch":{"k":"cicatrisation","cap":"Le pansement s'adapte à chaque phase de la cicatrisation."},"m":[{"dci":"Sulfadiazine argentique","br":"Flammazine®","pr":"crème : brûlures (courte durée)"},{"dci":"Hydrogels","br":"Purilon®, Intrasite®","pr":"détersion des plaies sèches, nécrotiques ou fibrineuses"},{"dci":"Alginates, hydrofibres","br":"Algostéril®, Aquacel®","pr":"plaies exsudatives, hémorragiques"},{"dci":"Hydrocolloïdes, hydrocellulaires (mousses)","br":"Comfeel®, Mepilex®, Allevyn®","pr":"bourgeonnement, épidermisation, prévention"},{"dci":"Pansements à l'argent, interfaces","br":"Urgotul Ag®, Aquacel Ag® ; Urgotul®, Adaptic®","pr":"plaies à risque infectieux ; protection du bourgeon"},{"dci":"Vaseline, tulle gras","br":"vaseline stérile","pr":"brûlures superficielles, épidermisation"}],"ind":["**Plaies chroniques** : escarres, ulcères de jambe, plaies du pied diabétique","**Plaies aiguës** : brûlures, dermabrasions, plaies post-opératoires, sites donneurs de greffe","Plaies colonisées ou à risque infectieux (argent, sur une durée limitée)"],"ci":["Allergie au produit (argent, sulfamides pour la sulfadiazine)","Sulfadiazine argentique : **nouveau-né**, grossesse à terme, déficit en G6PD, application très étendue prolongée","Hydrocolloïdes : **plaie infectée**, ischémique (artériopathie) ou très exsudative"],"ef":["Douleur au retrait (pansements adhérents), macération des berges, irritation","Coloration grisâtre de la plaie (argent)"],"eg":["Infection masquée sous un pansement occlusif inadapté","Sulfadiazine argentique : leucopénie, réactions cutanées (application étendue)"],"it":[],"v":[],"sc":["**Évolution de la plaie** : dimensions (mesures, photos), couleur, exsudat, odeur, berges, peau autour","**Douleur** (avant, pendant, après la réfection : antalgie anticipée)","Signes d'infection : rougeur qui s'étend, chaleur, œdème, pus, odeur, fièvre"],"sb":["Albuminémie, état nutritionnel ; prélèvement bactériologique seulement si signes cliniques d'infection"],"p":[],"edu":[],"cat":[],"r":["Choix selon le **stade** (noir, jaune, rouge, rose) et l'**exsudat** ; **milieu humide**","**Traiter la cause** : décharge, contention, nutrition, diabète","Pas d'hydrocolloïde sur une plaie infectée ou ischémique","Sulfadiazine : brûlures, cure courte, contre-indiquée chez le nouveau-né"],"err":[],"q":[],"f":["s:choix-pansement","s:pansement-escarre","s:pansement-brulure","m:antiseptiques"],"_l":1},
{"n":"Collyres : antibiotiques, anti-inflammatoires, antiallergiques et substituts lacrymaux","i":"collyres","s":"ophorl","nn":["Collyres antibiotiques","Collyres anti-inflammatoires","Collyres corticoïdes","Substituts lacrymaux","Collyres antiallergiques","Antihistaminiques locaux","Instillation de collyre"],"d":["Les **collyres** traitent les affections de la surface de l'œil : **conjonctivite** bactérienne (antibiotiques), allergique (antiallergiques), **sécheresse oculaire** (substituts lacrymaux), **inflammation** après chirurgie (corticoïdes, AINS). La **technique d'instillation** conditionne leur efficacité et leur tolérance.","Un **œil rouge et douloureux avec baisse de la vision** n'est pas une simple conjonctivite : il impose un avis ophtalmologique urgent (glaucome aigu, kératite, uvéite)."],"ma":["Chaque collyre agit localement : les **antibiotiques** détruisent les bactéries de la conjonctive ; les **corticoïdes** et les **AINS** diminuent l'inflammation ; les **antiallergiques** bloquent l'histamine ou stabilisent les mastocytes ; les **substituts lacrymaux** remplacent ou complètent le film de larmes."],"sch":{"k":"oeil","cap":"Les collyres agissent sur la surface de l'œil : conjonctive et cornée."},"m":[{"dci":"Azithromycine, tobramycine, rifamycine","br":"Azyter®, Tobrex®, Rifamycine Chibret®","pr":"antibiotiques (conjonctivite bactérienne)"},{"dci":"Dexaméthasone ; dexaméthasone + antibiotique","br":"Dexafree®, Maxidrol®, Chibroxine®","pr":"corticoïdes (sur prescription ophtalmologique)"},{"dci":"Indométacine, kétorolac","br":"Indocollyre®, Acular®","pr":"AINS (après chirurgie de la cataracte)"},{"dci":"Cromoglycate, olopatadine, kétotifène","br":"Opticron®, Opatanol®, Zaditen®","pr":"antiallergiques"},{"dci":"Larmes artificielles, gels","br":"Artelac®, Vismed®, Lacrifluid® ; sérum physiologique","pr":"substituts lacrymaux (unidoses sans conservateur)"}],"ind":["Conjonctivite bactérienne (sécrétions purulentes, paupières collées)","Conjonctivite allergique saisonnière ou perannuelle","Sécheresse oculaire (écrans, âge, port de lentilles, médicaments), patient inconscient (prévention de la kératite d'exposition)","Inflammation après chirurgie oculaire (corticoïdes, AINS)"],"ci":["**Corticoïdes** : **kératite herpétique**, ulcère de cornée, infection fongique ; jamais sans avis ophtalmologique devant un œil rouge non diagnostiqué","Allergie au principe actif ou au conservateur (chlorure de benzalkonium)","Port de lentilles pendant le traitement (selon le produit)"],"ef":["Picotements, brûlures à l'instillation, vision trouble transitoire","Goût amer (passage par le canal lacrymal)"],"eg":["Corticoïdes : **hypertonie oculaire, glaucome**, **cataracte** (usage prolongé), aggravation d'une infection herpétique ou fongique","Allergie locale (eczéma des paupières), toxicité des conservateurs sur la cornée (usage prolongé)"],"it":["Plusieurs collyres : **attendre 5 à 10 minutes** entre deux instillations (le gel en dernier)"],"v":["**Technique** : se laver les mains, tête inclinée en arrière, regarder vers le haut, **tirer la paupière inférieure** et instiller **une goutte dans le cul-de-sac conjonctival**, **sans toucher l'œil ni les cils** avec l'embout","Fermer l'œil doucement et **appuyer sur l'angle interne** (canal lacrymal) pendant 1 à 2 minutes : moins de passage dans le sang, plus d'effet local","Retirer les **lentilles** avant et attendre 15 minutes avant de les remettre ; flacon personnel, **date d'ouverture notée** (jeter en général après 15 à 28 jours) ; unidoses jetées après usage","Nettoyer les sécrétions au sérum physiologique, de l'angle interne vers l'angle externe, une compresse par œil"],"sc":["Rougeur, sécrétions, douleur, **vision**, photophobie","Tolérance (picotements, allergie)","Respect de la technique et du rythme d'instillation"],"sb":["Prélèvement conjonctival si conjonctivite sévère, du nouveau-né ou résistante"],"p":["Personne âgée : aide à l'instillation (tremblements), dispositifs d'aide, sécheresse fréquente","Nourrisson : conjonctivite du nouveau-né à prendre au sérieux (prélèvement) ; nettoyage au sérum physiologique","Grossesse et allaitement : la plupart utilisables ; comprimer le canal lacrymal"],"edu":["Technique d'instillation, hygiène des mains, linge de toilette personnel (conjonctivite contagieuse)","Ne pas utiliser un ancien collyre, ne pas le partager","**Consulter en urgence** en cas d'œil rouge douloureux, de baisse de la vision, de sensibilité à la lumière"],"cat":["Œil rouge et douloureux avec baisse de la vision : avis ophtalmologique **urgent**","Allergie au collyre (paupières gonflées, eczéma) : arrêter, prévenir","Erreur de collyre ou d'œil : rincer au sérum physiologique, prévenir"],"r":["Une goutte dans le **cul-de-sac conjonctival**, sans toucher l'œil, **pression sur l'angle interne**","**5 à 10 minutes** entre deux collyres ; date d'ouverture notée","**Corticoïdes jamais sans avis ophtalmologique** (herpès, glaucome)","Œil rouge douloureux avec baisse de vision = urgence"],"err":[],"q":[{"q":"Où instiller une goutte de collyre ?","o":["Directement sur la cornée","Dans le cul-de-sac conjonctival, en tirant la paupière inférieure","Dans l'angle interne de l'œil"],"a":1,"e":"Le cul-de-sac conjonctival retient la goutte sans toucher la cornée."},{"q":"Combien de temps attendre entre deux collyres différents ?","o":["Aucun délai","5 à 10 minutes","2 heures"],"a":1,"e":"Le délai évite que la deuxième goutte ne chasse la première."}],"f":["m:glaucome","m:mydriatiques","m:atb-locaux"]},
{"n":"Collyres antiglaucomateux","i":"glaucome","s":"ophorl","nn":["Collyres antiglaucomateux","Analogues des prostaglandines","Bêtabloquants ophtalmiques","Inhibiteurs de l'anhydrase carbonique","Glaucome","Latanoprost","Timolol","Acétazolamide"],"d":["Le **glaucome chronique** est une atteinte du nerf optique, souvent liée à une **pression intraoculaire** élevée, qui réduit progressivement et **sans douleur** le champ visuel jusqu'à la cécité. Le traitement, quotidien et **à vie**, abaisse la pression intraoculaire."],"ma":["Les collyres diminuent la pression dans l'œil : les **analogues des prostaglandines** augmentent l'évacuation de l'humeur aqueuse ; les **bêtabloquants**, les **inhibiteurs de l'anhydrase carbonique** et les **alpha-2 agonistes** diminuent sa production ; la **pilocarpine** contracte la pupille et ouvre l'angle."],"sch":{"k":"oeil","cap":"L'humeur aqueuse produite dans l'œil doit s'évacuer : son accumulation fait monter la pression."},"m":[{"dci":"Latanoprost, travoprost, bimatoprost","br":"Xalatan®, Travatan®, Lumigan®","pr":"analogues des prostaglandines, 1 goutte le soir"},{"dci":"Timolol","br":"Timoptol®, Geltim®","pr":"bêtabloquant"},{"dci":"Dorzolamide, brinzolamide","br":"Trusopt®, Azopt®","pr":"inhibiteurs de l'anhydrase carbonique"},{"dci":"Brimonidine","br":"Alphagan®","pr":"alpha-2 agoniste"},{"dci":"Associations fixes","br":"Xalacom®, Cosopt®, Azarga®","pr":"deux principes actifs"},{"dci":"Acétazolamide","br":"Diamox®","pr":"oral ou IV (crise aiguë, hypertonie importante)"}],"ind":["**Glaucome chronique à angle ouvert**, hypertonie oculaire","**Crise de glaucome aigu** : acétazolamide IV, collyres hypotonisants, pilocarpine, puis laser"],"ci":["Bêtabloquants : **asthme**, BPCO sévère, **bradycardie**, bloc auriculoventriculaire","Brimonidine : enfant de moins de 2 ans","Acétazolamide : insuffisance rénale ou hépatique sévère, hypokaliémie, allergie aux sulfamides"],"ef":["Analogues des prostaglandines : **rougeur oculaire**, **assombrissement de l'iris**, **allongement des cils**, pigmentation des paupières","Picotements, sécheresse oculaire","Acétazolamide : **fourmillements** des extrémités, fatigue, troubles digestifs"],"eg":["Bêtabloquants en collyre : **effets généraux** (bradycardie, malaise, **bronchospasme**, hypotension)","Acétazolamide : **hypokaliémie**, acidose, lithiase rénale","Brimonidine : somnolence, allergie"],"it":[],"v":[],"sc":["Observance, technique d'instillation","Pouls, dyspnée (timolol), rougeur oculaire","Douleur oculaire, halos, baisse de vision (crise aiguë)"],"sb":["Kaliémie sous acétazolamide ; suivi ophtalmologique (pression, champ visuel, nerf optique)"],"p":[],"edu":[],"cat":[],"r":["Glaucome chronique : baisse **silencieuse** du champ visuel ; traitement **à vie**","Prostaglandines le soir (iris foncé, cils longs) ; **timolol** : effets généraux (asthme, bradycardie)","**Glaucome aigu** = œil rouge douloureux, vision floue, halos, vomissements : urgence"],"err":[],"q":[],"f":["m:collyres","m:mydriatiques","m:bb"],"_l":1},
{"n":"Mydriatiques et cycloplégiques","i":"mydriatiques","s":"ophorl","nn":["Mydriatiques","Cycloplégiques","Collyre atropine","Tropicamide"],"d":["Les **mydriatiques** dilatent la pupille pour examiner le **fond d'œil** ou préparer une chirurgie ; les **cycloplégiques** paralysent aussi l'accommodation (mesure de la réfraction chez l'enfant, traitement de l'uvéite). Ils sont très utilisés en consultation d'ophtalmologie et en préopératoire."],"ma":["Les **anticholinergiques** (tropicamide, cyclopentolate, atropine) bloquent le muscle qui resserre la pupille et celui de l'accommodation ; les **sympathomimétiques** (phényléphrine) stimulent le muscle dilatateur de la pupille."],"sch":null,"m":[{"dci":"Tropicamide","br":"Mydriaticum®","pr":"action courte (quelques heures)"},{"dci":"Phényléphrine","br":"Néosynéphrine® collyre","pr":"mydriase (associée au tropicamide)"},{"dci":"Cyclopentolate","br":"Skiacol®","pr":"cycloplégie (réfraction de l'enfant)"},{"dci":"Atropine","br":"Atropine collyre","pr":"cycloplégie prolongée (7 à 10 jours), uvéite, amblyopie"}],"ind":["Examen du fond d'œil, préparation à la chirurgie de la cataracte ou de la rétine","Mesure de la réfraction chez l'enfant (cycloplégie)","**Uvéite** (prévention des synéchies), certaines amblyopies (atropine)"],"ci":["**Glaucome à angle fermé** ou angle étroit (risque de crise aiguë)","Phényléphrine : HTA sévère, maladie coronaire, hyperthyroïdie","Atropine : enfant fébrile ou trisomique (sensibilité accrue)"],"ef":["**Vision floue**, **éblouissement** (photophobie) pendant plusieurs heures (jours pour l'atropine)","Picotements à l'instillation"],"eg":["**Crise de glaucome aigu** chez un patient à angle étroit","Effets généraux chez l'enfant (atropine, cyclopentolate) : **agitation**, hallucinations, fièvre, tachycardie, rougeur, sécheresse","Phényléphrine : poussée hypertensive, troubles du rythme"],"it":[],"v":[],"sc":["Douleur oculaire, rougeur, baisse de vision, nausées (crise de glaucome)","Chez l'enfant : agitation, fièvre, rougeur du visage, pouls","Tension (phényléphrine chez le patient cardiaque)"],"sb":["Aucune"],"p":[],"edu":[],"cat":[],"r":["Dilatent la pupille (fond d'œil, chirurgie) ± paralysent l'accommodation","**Pas de conduite** 4 à 6 h ; vision floue et photophobie","Contre-indiqués en cas d'**angle étroit** (glaucome aigu) ; effets généraux chez l'enfant"],"err":[],"q":[],"f":["m:glaucome","m:anticholinergiques"],"_l":1},
{"n":"Traitements ORL locaux et des vertiges","i":"orl-nasal","s":"ophorl","nn":["Corticoïdes nasaux","Décongestionnants nasaux","Antibiotiques ORL","Traitements des vertiges","Traitements des acouphènes selon leur cause","Lavage de nez","Pseudoéphédrine"],"d":["Les traitements ORL locaux comprennent les **lavages de nez** au sérum physiologique, les **corticoïdes nasaux** (rhinite allergique, polypose), les **décongestionnants** (à usage très court et très encadré) et les gouttes auriculaires. Les **vertiges** se traitent selon leur cause (manœuvre libératoire, antivertigineux en cure courte)."],"ma":["Les **corticoïdes nasaux** diminuent l'inflammation de la muqueuse nasale ; les **décongestionnants** (vasoconstricteurs alpha) resserrent les vaisseaux de la muqueuse ; le **lavage** élimine mucus et allergènes. Les **antivertigineux** (acétylleucine, bétahistine, antihistaminiques) atténuent les symptômes vestibulaires."],"sch":null,"m":[{"dci":"Sérum physiologique, eau de mer","br":"Physiomer®, unidoses de NaCl 0,9 %","pr":"lavage de nez (nourrisson et adulte)"},{"dci":"Mométasone, fluticasone, béclométasone","br":"Nasonex®, Avamys®, Béconase®","pr":"corticoïdes nasaux"},{"dci":"Oxymétazoline, pseudoéphédrine","br":"Aturgyl®, Dérinox® ; associations orales (Actifed rhume®…)","pr":"vasoconstricteurs (déconseillés)"},{"dci":"Acétylleucine, bétahistine","br":"Tanganil®, Serc®","pr":"vertiges"},{"dci":"Ofloxacine auriculaire","br":"Oflocet® auriculaire","pr":"otite externe (voir antibiotiques locaux)"}],"ind":["**Rhinite allergique**, polypose nasosinusienne, sinusite chronique (corticoïdes nasaux)","Rhume, nez bouché du nourrisson (lavage de nez)","Vertiges aigus (cure courte d'antivertigineux), vertige positionnel paroxystique bénin (manœuvre libératoire)"],"ci":["**Vasoconstricteurs** : **enfant de moins de 15 ans**, HTA, antécédent d'AVC ou d'infarctus, glaucome à angle fermé, rétention urinaire, association à un autre vasoconstricteur, grossesse","Corticoïdes nasaux : infection locale non traitée, épistaxis récidivantes","Gouttes auriculaires : tympan perforé (selon le produit)"],"ef":["Corticoïdes nasaux : **saignements de nez**, sécheresse, irritation","Vasoconstricteurs : rebond de congestion (rhinite médicamenteuse), insomnie, palpitations","Antivertigineux : somnolence (antihistaminiques)"],"eg":["Vasoconstricteurs : **AVC**, **infarctus**, poussée hypertensive, convulsions","Corticoïdes nasaux : perforation de la cloison (rare, mauvaise technique)"],"it":[],"v":[],"sc":["Obstruction nasale, écoulement, saignements","Tension, palpitations (vasoconstricteurs)","Vertiges : intensité, nystagmus, nausées, signes neurologiques associés (urgence)"],"sb":["Aucune"],"p":[],"edu":[],"cat":[],"r":["**Lavage de nez** au sérum physiologique : base des soins ORL, surtout chez le nourrisson","Corticoïdes nasaux : rhinite allergique, embout vers l'extérieur","**Vasoconstricteurs déconseillés** (AVC, infarctus), interdits avant 15 ans, 5 jours maximum","Vertige avec signes neurologiques = urgence"],"err":[],"q":[],"f":["m:antih1","m:atb-locaux"],"_l":1}
]);
